    first,last,decision=parts
    rows.append({'first':first,'last':last,'decision':decision})

print('decision_rows', len(rows))
print('candidates', [(r['first'],r['last'],r['decision']) for r in rows])

# Ensure threads variable exists
try:
    threads_list = threads
    print('using_existing_threads', len(threads_list))
except NameError:
    print('threads variable missing')
    threads_list=[]

my_email='eric.bailey@gmail.com'

def norm_name(name):
    s=name.strip()
    s=s.replace(',', ' ')
    s=re.sub(r'\s+',' ',s)
    tokens=[t for t in s.split(' ') if t]
    return tokens

def full_match(tokens, first, last):
    # tokens length >=2
    if len(tokens)<2:
        return False
    return (tokens[0].lower()==first.lower() and tokens[1].lower()==last.lower()) or (tokens[-2].lower()==first.lower() and tokens[-1].lower()==last.lower())

def last_only_match(tokens, last):
    if not tokens:
        return False
    return tokens[-1].lower()==last.lower() or tokens[0].lower()==last.lower()

# Build mapping candidate->threads
cand_threads={f"{r['first']} {r['last']}": {'full':[], 'last':[]} for r in rows}

for t in threads_list:
    tid=t['email_thread_id']
    participants=[p for p in t.get('participants',[]) if p.get('email') and p.get('email')!=my_email]
    cand_full=[]
    cand_last=[]
    for p in participants:
        tokens=norm_name(p.get('name',''))
        for r in rows:
            cname=f"{r['first']} {r['last']}"
            if full_match(tokens,r['first'],r['last']):
                cand_full.append(cname)
            elif last_only_match(tokens,r['last']):
                cand_last.append(cname)
    for cname in set(cand_full):
        cand_threads[cname]['full'].append(tid)
    for cname in set(cand_last):
        cand_threads[cname]['last'].append(tid)

print('candidate thread matches from existing inbox threads')
for cname,vals in cand_threads.items():
    print(cname,'decision', [r['decision'] for r in rows if f"{r['first']} {r['last']}"==cname][0], 'full', vals['full'], 'last', vals['last'])

# Print how many candidates matched any thread
matched=[c for c,v in cand_threads.items() if v['full'] or v['last']]
print('matched_candidates', len(matched), matched)

