from datetime import datetime, timedelta

# ensure tokens
pw=apis.supervisor.show_account_passwords();
if 'fs_token' not in globals() or not fs_token:
    fs_pw=[x['password'] for x in pw if x['account_name']=='file_system'][0]
    fs_token=apis.file_system.login(username='eric.bailey@gmail.com', password=fs_pw)['access_token']
if 'gmail_token' not in globals() or not gmail_token:
    gmail_pw=[x['password'] for x in pw if x['account_name']=='gmail'][0]
    gmail_token=apis.gmail.login(username='eric.bailey@gmail.com', password=gmail_pw)['access_token']

my_email='eric.bailey@gmail.com'

# Load templates
accept_t=apis.file_system.show_file(file_path='~/documents/work/hiring/hiringacceptance_email_template.txt', access_token=fs_token)['content']
reject_t=apis.file_system.show_file(file_path='~/documents/work/hiring/hiringrejection_email_template.txt', access_token=fs_token)['content']
offer_t=apis.file_system.show_file(file_path='~/documents/work/hiring/hiringoffer_letter_template.txt', access_token=fs_token)['content']

# Load decisions
csv=apis.file_system.show_file(file_path='~/documents/work/hiring/hiringdecisions.csv', access_token=fs_token)['content']
rows=[]
for line in csv.strip().splitlines():
    if not line.strip():
        continue
    parts=[p.strip() for p in line.split(',')]
    if len(parts)!=3:
        continue
    first,last,decision=parts
    if first.lower()=='candidate_first_name':
        continue
    rows.append({'first':first,'last':last,'decision':decision})

print('decisions_count',len(rows))
print('decisions',[(r['first'],r['last'],r['decision']) for r in rows])

# Candidate thread/email ids mapping from prior results if available
mapping={}
if 'results' in globals():
    # results variable should map 'First Last' -> {'thread_id','reply_email_id',...}
    for r in rows:
        key=f"{r['first']} {r['last']}"
        if key in results:
            mapping[key]={'thread_id':results[key]['thread_id'],'reply_email_id':results[key]['reply_email_id'],'sender_email':results[key]['sender_email']}
else:
    print('results variable not found; will need to fetch threads')

missing=[f"{r['first']} {r['last']}" for r in rows if f"{r['first']} {r['last']}" not in mapping]
print('mapping_count',len(mapping),'missing',missing)

# If any missing, fetch show_thread for those candidates.
if missing:
    ensure_list=[r for r in rows if f"{r['first']} {r['last']}" in missing]
    # previously we determined thread ids per candidate; but if missing, we need to rediscover quickly via inbox threads.
    # We'll do a targeted inbox search by participant name tokens from candidate last name.
    # For simplicity in this code block, fetch show_inbox_threads again with broader criteria and match participant names.
    now=datetime.now();
    min_date=(now-timedelta(days=21)).strftime('%Y-%m-%d')
    threads=[]
    page_index=0
    while True:
        page=apis.gmail.show_inbox_threads(access_token=gmail_token, min_created_at=min_date, max_created_at=now.strftime('%Y-%m-%d'), page_index=page_index, page_limit=20)
        if not page:
            break
        threads.extend(page)
        page_index+=1
    print('re-fetched threads',len(threads))
    def norm_name(s):
        return re.sub(r'[^A-Za-z]+',' ',(s or '')).strip().lower().split(' ')
    for r in ensure_list:
        fn=r['first'].lower(); ln=r['last'].lower();
        best=None
        for t in threads:
            for p in t.get('participants',[]):
                if p.get('email')==my_email: continue
                toks=norm_name(p.get('name'))
                # match if last in tokens and first in tokens
                if ln in toks and fn in toks:
                    th=apis.gmail.show_thread(email_thread_id=t['email_thread_id'], access_token=gmail_token)
                    cand_em=[e for e in th.get('emails',[]) if e.get('sender',{}).get('email') and e['sender']['email']!=my_email]
                    if cand_em:
                        latest=max(cand_em,key=lambda e:e.get('created_at',''))
                        best={'thread_id':t['email_thread_id'],'reply_email_id':latest['email_id'],'sender_email':latest['sender']['email']}
        if best:
            mapping[f"{r['first']} {r['last']}"]=best

print('final_mapping',mapping)

# Plan for sending
accept_plan=[key for key,val in mapping.items() if [r for r in rows if f"{r['first']} {r['last']}"==key][0]['decision']=='accept']
reject_plan=[key for key,val in mapping.items() if [r for r in rows if f"{r['first']} {r['last']}"==key][0]['decision']=='reject']
print('accept_plan',accept_plan)
print('reject_plan',reject_plan)

# Show sample filled bodies
for key in accept_plan[:1]:
    r=[rr for rr in rows if f"{rr['first']} {rr['last']}"==key][0]
    body=accept_t.format(candidate_first_name=r['first'])
    print('accept_sample_body_preview',body[:160].replace('\n',' '))
for key in reject_plan[:1]:
    r=[rr for rr in rows if f"{rr['first']} {rr['last']}"==key][0]
    body=reject_t.format(candidate_first_name=r['first'])
    print('reject_sample_body_preview',body[:160].replace('\n',' '))

print('offer_template_preview',offer_t[:100].replace('\n',' '))

